package io.github.jesterportfolio.hearth.survival.housing;

import java.util.*;
import java.nio.charset.StandardCharsets;

/** 실행 수치는 콘텐츠로 분리합니다. 기존 가격표는 주택에 고정하여 새 가격표와 구분합니다. */
public record HousingSettings(Catalog catalog,boolean allowNew,boolean purchases,int maxMembers,int maxLoaded,int idleSeconds,int resourceRadius,List<Plot> plots){
 public record Tier(String id,int width,long price){public Tier{key(id);if(width<16||width>2048||width%16!=0||price<0||price>1_000_000_000_000L)throw new IllegalArgumentException("HOUSING_TIER");}}
 public record Catalog(String version,List<Tier> tiers){public Catalog{key(version);tiers=List.copyOf(tiers);if(tiers.isEmpty()||tiers.size()>8)throw new IllegalArgumentException("HOUSING_CATALOG");var ids=new HashSet<String>();for(int i=0;i<tiers.size();i++){var t=tiers.get(i);if(!ids.add(t.id())||i>0&&(t.width()<=tiers.get(i-1).width()||t.price()<=tiers.get(i-1).price()))throw new IllegalArgumentException("HOUSING_CATALOG_ORDER");}}public String packed(){return String.join(";",tiers.stream().map(t->t.id()+","+t.width()+","+t.price()).toList());}public String hash(){return digest(version+"/"+packed());}public long cost(int before,int after){if(after<0||after>=tiers.size()||before>=after||before< -1)throw new IllegalArgumentException("HOUSING_UPGRADE");return tiers.get(after).price()-(before<0?0:tiers.get(before).price());}public static Catalog unpack(String version,String raw){if(raw.length()>4096)throw new IllegalArgumentException("HOUSING_CATALOG");return new Catalog(version,Arrays.stream(raw.split(";",-1)).map(row->{var p=row.split(",",-1);if(p.length!=3)throw new IllegalArgumentException("HOUSING_CATALOG");return new Tier(p[0],Integer.parseInt(p[1]),Long.parseLong(p[2]));}).toList());}}
 public record Plot(String id,int x,int z,int width,int height){public Plot{key(id);if(Math.abs((long)x)>100000||Math.abs((long)z)>100000||width<8||width>64||height<8||height>128)throw new IllegalArgumentException("HOUSING_PLOT");}public boolean overlaps(Plot b){return x<b.x+b.width&&b.x<x+width&&z<b.z+b.width&&b.z<z+width;}}
 public HousingSettings{plots=List.copyOf(plots);if(maxMembers<1||maxMembers>64||maxLoaded<1||maxLoaded>16||idleSeconds<10||idleSeconds>86400||resourceRadius<2||resourceRadius>64||plots.size()>256)throw new IllegalArgumentException("HOUSING_SETTINGS");var ids=new HashSet<String>();for(int i=0;i<plots.size();i++){var a=plots.get(i);if(!ids.add(a.id())||a.x()<resourceRadius&&a.x()+a.width()>-resourceRadius&&a.z()<resourceRadius&&a.z()+a.width()>-resourceRadius)throw new IllegalArgumentException("HOUSING_PLOT_SPAWN");for(int j=0;j<i;j++)if(a.overlaps(plots.get(j)))throw new IllegalArgumentException("HOUSING_PLOT_OVERLAP");}}
 public String geometryHash(){return digest("housing-v1/"+plots+"/"+resourceRadius);}
 private static void key(String s){if(s==null||!s.matches("[a-z][a-z0-9_]{0,31}"))throw new IllegalArgumentException("HOUSING_KEY");}
 private static String digest(String s){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private static String text(Properties p,String k){return Objects.requireNonNull(p.getProperty(k),k).strip();}private static int n(Properties p,String k){return Integer.parseInt(text(p,k));}private static boolean bool(Properties p,String k){var v=text(p,k);if(!Set.of("true","false").contains(v))throw new IllegalArgumentException("HOUSING_BOOLEAN");return Boolean.parseBoolean(v);}
 public static HousingSettings parse(Properties p){var tiers=Arrays.stream(text(p,"tiers").split(",",-1)).map(String::strip).map(id->new Tier(id,n(p,"tier."+id+".width"),Long.parseLong(text(p,"tier."+id+".price")))).toList();var plots=new ArrayList<Plot>();String raw=text(p,"plots");if(!raw.isEmpty())for(String id:raw.split(",",-1)){String k="plot."+id.strip()+".";plots.add(new Plot(id.strip(),n(p,k+"x"),n(p,k+"z"),n(p,k+"width"),n(p,k+"height")));}return new HousingSettings(new Catalog(text(p,"price-version"),tiers),bool(p,"allow-new-policy"),bool(p,"purchases-enabled"),n(p,"max-members"),n(p,"max-loaded-worlds"),n(p,"idle-seconds"),n(p,"resource-spawn-radius"),plots);}
}
